const std = @import("std");
const Date = struct {
    y: i32,
    m: u32,
    d: u32,
    h: u32,
    min: u32,
    sec: u32,
    fn leap(s: Date) bool {
        return @mod(s.y, 4) == 0 and (@mod(s.y, 100) != 0 or @mod(s.y, 400) == 0);
    }
    fn days(s: Date) u32 {
        return switch (s.m) {
            2 => if (s.leap()) 29 else 28,
            4, 6, 9, 11 => 30,
            else => 31,
        };
    }
    fn next(s: *Date) void {
        s.d += 1;
        if (s.d > s.days()) {
            s.d = 1;
            s.m += 1;
            if (s.m > 12) {
                s.m = 1;
                s.y += 1;
            }
        }
    }
    fn prev(s: *Date) void {
        if (s.d > 1) {
            s.d -= 1;
            return;
        }
        if (s.m > 1) s.m -= 1 else {
            s.m = 12;
            s.y -= 1;
        }
        s.d = s.days();
    }
    fn weekday(s: Date) u32 {
        const offsets = [_]i32{ 0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4 };
        const y = s.y - (if (s.m < 3) @as(i32, 1) else 0);
        return @intCast(@mod(y + @divFloor(y, 4) - @divFloor(y, 100) + @divFloor(y, 400) + offsets[s.m - 1] + @as(i32, @intCast(s.d)), 7));
    }
};
fn num(s: []const u8) !u32 {
    return std.fmt.parseInt(u32, s, 10);
}
pub fn deliveryDate(a: std.mem.Allocator, start: []const u8, description: []const u8) ![]u8 {
    if (start.len != 19) return error.InvalidDate;
    var d = Date{ .y = @intCast(try num(start[0..4])), .m = try num(start[5..7]), .d = try num(start[8..10]), .h = try num(start[11..13]), .min = try num(start[14..16]), .sec = try num(start[17..19]) };
    if (std.mem.eql(u8, description, "NOW")) {
        d.h += 2;
        if (d.h >= 24) {
            d.h -= 24;
            d.next();
        }
    } else if (std.mem.eql(u8, description, "ASAP")) {
        if (d.h < 13) d.h = 17 else {
            d.next();
            d.h = 13;
        }
        d.min = 0;
        d.sec = 0;
    } else if (std.mem.eql(u8, description, "EOW")) {
        const w = d.weekday();
        const target: u32 = if (w >= 1 and w <= 3) 5 else 0;
        while (d.weekday() != target) d.next();
        d.h = if (target == 5) 17 else 20;
        d.min = 0;
        d.sec = 0;
    } else if (description.len >= 2 and description[description.len - 1] == 'M') {
        const month = try num(description[0 .. description.len - 1]);
        if (month < 1 or month > 12) return error.InvalidDescription;
        if (d.m >= month) d.y += 1;
        d.m = month;
        d.d = 1;
        while (d.weekday() == 0 or d.weekday() == 6) d.next();
        d.h = 8;
        d.min = 0;
        d.sec = 0;
    } else if (description.len == 2 and description[0] == 'Q') {
        const q = try num(description[1..]);
        if (q < 1 or q > 4) return error.InvalidDescription;
        if ((d.m + 2) / 3 > q) d.y += 1;
        d.m = q * 3;
        d.d = d.days();
        while (d.weekday() == 0 or d.weekday() == 6) d.prev();
        d.h = 8;
        d.min = 0;
        d.sec = 0;
    } else return error.InvalidDescription;
    return std.fmt.allocPrint(a, "{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}", .{ @as(u32, @intCast(d.y)), d.m, d.d, d.h, d.min, d.sec });
}

